namespace ghidra.app.plugin.core.functiongraph.graph.vertex;

using ghidra.app.util.viewer.format;
using ghidra.app.util.viewer.listingpanel;
using ghidra.framework.model;
using ghidra.program.model.listing;

class FGVertexListingModel : ProgramBigListingModel {

	private bool isDirty;

	FGVertexListingModel(Program program, FormatManager formatManager) : base(program, formatManager)
    {
	}

	bool refresh() {
		if (!isDirty) {
			return false;
		}

		isDirty = false;

		if (!program.isClosed()) {
			notifyDataChanged(true);
			return true;
		}
		return false;
	}

	/* @Override */
	public void domainObjectChanged(DomainObjectChangedEvent ev) {
		isDirty = true;
	}
}
